n = int(input())

# Read friendship graph
friends = [[] for _ in range(n + 1)]
k = int(input())
for _ in range(k):
    u, v = map(int, input().split())
    friends[u].append(v)
    friends[v].append(u)

# Read dislike pairs
dislikes = set()
m = int(input())
for _ in range(m):
    u, v = map(int, input().split())
    dislikes.add((min(u, v), max(u, v)))


def dfs(node, visited, component):
    """Find connected component using DFS"""
    visited[node] = True
    component.append(node)

    for neighbor in friends[node]:
        if not visited[neighbor]:
            dfs(neighbor, visited, component)

# Find all connected components
visited = [False] * (n + 1)
largest_valid_size = 0

for start in range(1, n + 1):
    if not visited[start]:
        component = []
        dfs(start, visited, component)

        # Check if this component is valid
        valid = True
        for i in range(len(component)):
            for j in range(i + 1, len(component)):
                if (component[i], component[j]) in dislikes:
                    valid = False
                    break
            if not valid:
                break

        if valid:
            largest_valid_size = max(largest_valid_size, len(component))

print(largest_valid_size)
