import sys

def solve(s):
    left = s.find('[')
    right = s.rfind(']')

    if left == -1 or right == -1:
        return -1
    if left >= right:
        return -1

    # Count colons between left and right
    colon_count = 0
    pipe_count = 0

    for ch in s[left:right+1]:
        if ch == ':':
            colon_count += 1
        elif ch == '|':
            pipe_count += 1

    if colon_count < 2:
        return -1

    # We can use 2 colons and all pipes between them
    return 2 + 2 + pipe_count

if __name__ == "__main__":
    s = sys.stdin.read().strip()
    print(solve(s))
"}

