import sys

def solve(s):
    left = s.find('[')
    right = s.rfind(']')

    if left == -1 or right == -1:
        return -1
    if left >= right:
        return -1

    # We need to find two colons such that:
    # 1. First colon is after left
    # 2. Second colon is before right
    # 3. Between the two colons, we can count |

    colons_after_left = []
    colons_before_right = []

    # Find colons after left and before right
    for i in range(left + 1, right):
        if s[i] == ':':
            colons_after_left.append(i)

    for i in range(left, right):
        if s[i] == ':':
            colons_before_right.append(i)

    if len(colons_after_left) < 1 or len(colons_before_right) < 2:
        return -1

    # Find the first colon after left
    first_colon = colons_after_left[0]
    # Find the last colon before right
    last_colon = colons_before_right[-1]

    # Count |
    pipe_count = 0
    for i in range(first_colon + 1, last_colon):
        if s[i] == '|':
            pipe_count += 1

    # Also need to count the second colon between first and last
    # Actually, we need to count the number of '|' between the two colons
    return 2 + 2 + pipe_count

if __name__ == "__main__":
    s = sys.stdin.read().strip()
    print(solve(s))
"}

