from collections import Counter

# Count frequency of each number
freq = Counter(nums)

max_len = 2  # Minimum length is 2

# Try all possible pairs for f0 and f1
for f0 in freq:
    for f1 in freq:
        # Create a copy of the frequency counter
        used = Counter(freq)

        # Check if we can use f0 and f1
        if f0 == f1:
            # Only need one instance
            if used[f0] > 0:
                used[f0] -= 1
        else:
            # Need at least one of each
            if used[f0] > 0 and used[f1] > 0:
                used[f0] -= 1
                used[f1] -= 1
            else:
                continue  # Can't form this pair

        # Try to extend the sequence
        current = 2
        while True:
            next_val = f0 + f1
            if used[next_val] > 0:
                used[next_val] -= 1
                f0, f1 = f1, next_val
                current += 1
            else:
                break

        max_len = max(max_len, current)

print(max_len)
