def solve():
    n = int(input())
    a = list(map(int, input().split()))
    total = sum(a)

    # Find all divisors of total greater than 1
    def get_divisors(total):
        divisors = set()
        for i in range(2, int(total**0.5) + 1):
            if total % i == 0:
                divisors.add(i)
                if total // i > 1:
                    divisors.add(total // i)
        return sorted(divisors)

    min_moves = float('inf')
    for d in get_divisors(total):
        prefix_sum = [0]
        for num in a:
            prefix_sum.append(prefix_sum[-1] + num)

        # dp[i] = minimum moves to make boxes 1..i all divisible by d
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            # Move all chocolates from box i to the right
            dp[i] = dp[i-1] + a[i-1]

            # Try to merge with box i-1
            if i > 1:
                # Boxes i-1 and i have sum prefix_sum[i] - prefix_sum[i-1]
                sum_segment = prefix_sum[i] - prefix_sum[i-1]

                # If we can make them both divisible by d
                # We need to move (sum_segment % d) * 2 moves
                remainder = sum_segment % d
                if remainder == 0:
                    dp[i] = min(dp[i], dp[i-1])
                else:
                    dp[i] = min(dp[i], dp[i-1] + sum_segment - 2 * remainder)

        min_moves = min(min_moves, dp[n])

    print(min_moves if min_moves != float('inf') else -1)

solve()
