import sys

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def get_next_prime(start, used):
    candidate = start
    while True:
        if candidate not in used and is_prime(candidate):
            return candidate
        candidate += 1

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    b = []
    used_primes = set()
    max_element_used = 0

    for ai in a:
        # Try to use a[i] if it's coprime with all previous elements
        coprime = True
        for bi in b:
            if ai % bi == 0:
                coprime = False
                break
        if coprime:
            b.append(ai)
            used_primes.add(ai)
            max_element_used = max(max_element_used, ai)
            continue

        # Find the smallest prime >= ai that's not used
        next_prime = get_next_prime(ai, used_primes)
        if next_prime is not None:
            b.append(next_prime)
            used_primes.add(next_prime)
            max_element_used = max(max_element_used, next_prime)
        else:
            # Need to reset - use the smallest prime > max_element_used
            next_prime = get_next_prime(max_element_used + 1, used_primes)
            b.append(next_prime)
            used_primes.add(next_prime)
            max_element_used = next_prime

    sys.stdout.write(' '.join(map(str, b)) + '\n')

if __name__ == "__main__":
    solve()
"}

