def solve():
    MOD = 10**9 + 7

    # Read input
    n, m = map(int, input().split())

    # Track blocked intervals for each row (0-indexed)
    blocked = [
        [],  # Row 1 (index 0)
        [],  # Row 2 (index 1)
        []   # Row 3 (index 2)
    ]

    for _ in range(n):
        a, l, r = map(int, input().split())
        # a is 1-indexed row, convert to 0-indexed
        row = a - 1
        blocked[row].append((l, r))

    # Sort each row's blocked intervals
    for i in range(3):
        blocked[i].sort()

    # DP: dp[i] = number of ways to reach row i (0-indexed) at current column
    dp = [0, 0, 0]
    dp[1] = 1  # We start at row 2 (0-indexed 1) column 1

    # Move from column 1 to column m
    for j in range(2, m + 1):
        # Current column j
        # Calculate new dp for column j
        new_dp = [0, 0, 0]

        # From previous column j-1
        for i in range(3):
            if dp[i] == 0:
                continue

            # Move to (i-1, j) if valid
            if i > 0:
                if not is_blocked(i - 1, j - 1, blocked):
                    new_dp[i - 1] = (new_dp[i - 1] + dp[i]) % MOD

            # Move to (i, j)
            if not is_blocked(i, j - 1, blocked):
                new_dp[i] = (new_dp[i] + dp[i]) % MOD

            # Move to (i+1, j) if valid
            if i < 2:
                if not is_blocked(i + 1, j - 1, blocked):
                    new_dp[i + 1] = (new_dp[i + 1] + dp[i]) % MOD

        dp = new_dp

    print(dp[1] % MOD)


def is_blocked(row, col, blocked):
    # Check if cell (row, col) is blocked
    for (l, r) in blocked[row]:
        if l <= col <= r:
            return True
    return False

solve()
