import sys
import math

def get_divisors(n):
    """Return all divisors of n in increasing order"""
    divisors = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    X = int(data[0])
    k = int(data[1])

    # Start with X
    sequence = [X]

    # For each level up to k
    for i in range(k):
        # Get all divisors for each number in the sequence
        divisors = []
        for num in sequence:
            divisors.extend(get_divisors(num))

        # Update sequence to be divisors
        sequence = divisors

        # If sequence exceeds 100,000 elements, truncate
        if len(sequence) > 100000:
            sequence = sequence[:100000]
            break

    # Print result with 6 spaces between each number, but not after the last
    print('  ' * 6, end=' ')
    for i, num in enumerate(sequence):
        print(num, end=' ')
        if i == len(sequence) - 1:
            print()

