import sys
import math

def get_divisors(n):
    """Get all divisors of n (excluding 1)"""
    divisors = set()
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            divisors.add(i)
            if n // i != i:
                divisors.add(n // i)
    if n > 1:
        divisors.add(n)
    return sorted(divisors)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Find all divisors of the sum
    s = sum(a)
    divisors = get_divisors(s)

    # If no valid divisors, check if s == 0 (but at least one a_i > 0)
    if not divisors:
        print(-1)
        return

    min_moves = float('inf')

    # Try each divisor
    for d in divisors:
        # We want to find the optimal prefix (up to which position i to be divisible by d)
        # We'll try making all prefixes up to position i divisible by d for each i

        # For each i, if prefix_sum > 0, we need to move (prefix_sum % d) pieces to later boxes
        # The moves needed = sum of (prefix_sum % d) for all positions

        prefix_sum = 0
        moves = 0

        for i in range(n):
            prefix_sum += a[i]
            if prefix_sum % d != 0:
                moves += prefix_sum % d
            else:
                # If prefix_sum == 0, we don't need to move anything
                pass

        min_moves = min(min_moves, moves)

    print(min_moves if min_moves != float('inf') else -1)

if __name__ == "__main__":
    solve()
