def get_cell(pos):
    if pos <= n:
        return (0, pos - 1)  # 0-indexed for first row
    else:
        return (1, pos - 1 - n)

def get_character(row, col):
    if row == 0:
        return first_row[col]
    else:
        return second_row[col]

