    r1, c1 = get_cell(v)
    r2, c2 = get_cell(u)

    if r1 == r2:
        # Same row
        if c1 == c2:
            return 0
        return abs(c1 - c2)
    else:
        # Different rows
        if c1 == c2:
            return 0
        distance = abs(c1 - c2) + 1

        # Check if there's a path through adjacent columns
        # There's no path if there's a completely blocked column between them
        if c1 < c2:
            start = c1 + 1
            end = c2
        else:
            start = c2 + 1
            end = c1

        for col in range(start, end):
            if get_character(0, col) == 'X' and get_character(1, col) == 'X':
                return -1

        return distance

for _ in range(m):
    v, u = map(int, input().split())
    print(shortest_path(v, u))
