from collections import defaultdict
from functools import lru_cache

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    q = int(data[0])
    results = []

    for i in range(q):
        b = int(data[1 + 3*i])
        l = int(data[2 + 3*i])
        r = int(data[3 + 3*i])

        # Function to count magic numbers <= N
        def count_magic(N):
            # Convert N to base b as a string
            digits = []
            temp = N
            if temp == 0:
                digits = [0]
            else:
                while temp > 0:
                    digits.append(temp % b)
                    temp //= b
            digits.reverse()

            # DP with memoization
            @lru_cache(maxsize=None)
            def dp(pos, mask, tight, started):
                if pos == len(digits):
                    # Check if all counts are even
                    return 1 if mask == 0 else 0

                limit = digits[pos] if tight else b-1
                total = 0

                for d in range(0, limit + 1):
                    new_mask = mask
                    new_tight = tight and (d == limit)
                    new_started = started or d > 0

                    if started:
                        if d == 0:
                            new_mask = mask & (~1)
                        else:
                            new_mask = mask | (1 << d)
                    else:
                        if d == 0:
                            # Skip leading zero
                            continue

                    total += dp(pos + 1, new_mask, new_tight, new_started)

                return total

            return dp(0, 0, True, False)

        # Count numbers in [l, r]
        count_r = count_magic(r)
        count_l_1 = count_magic(l - 1)
        results.append(count_r - count_l_1)

    sys.stdout.write("\n".join(map(str, results)))

solve()
"}

