def divisors(n):
    """Return a list of divisors of n in increasing order"""
    divs = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(divs)

def f(seq):
    """Apply function f to sequence seq"""
    result = []
    for num in seq:
        result.extend(divisors(num))
    return result


def solve():
    X, k = map(int, input().split())

    if k == 0:
        print(X)
        return

    current_seq = [X]

    # We'll track seen sequences to detect period
    seen = {}

    while k > 0:
        seq_tuple = tuple(current_seq)

        if seq_tuple in seen:
            # Found a period
            period = seen[seq_tuple]
            remaining = k - period
            k = remaining % period
            if k == 0:
                break
            # Reset to the start of the period
            current_seq = list(seen[seq_tuple][0])
            continue

        seen[seq_tuple] = (current_seq[:], k)  # Store the sequence and remaining k

        # If we're at k, we're done
        if k == 1:
            break

        # Generate next sequence
        next_seq = f(current_seq)

        # If the sequence is too long, we can just output the first 100,000 elements
        if len(next_seq) > 100000:
            result = next_seq[:100000]
            break

        current_seq = next_seq
        k -= 1

    # If we exited normally, output current_seq or the result
    if 'result' in locals():
        print(' '.join(map(str, result)))
    else:
        print(' '.join(map(str, current_seq)))

solve()
