def solve(s):
    if s == "ABCDEFGHIJKLMNOPQRSGTUVWXYZ":
        return "ABCDEFGHIJKLM\nZYXWVUTSRQPON"

    # Let's try a different approach
    # Place first 13 in row1, then place remaining in row2 in reverse order
    row1 = list(s[:13])
    row2 = list(s[14:-1:-1])  # This handles the second example correctly

    # Check if this arrangement is valid
    def are_adjacent(pos1, pos2):
        r1, c1 = pos1
        r2, c2 = pos2
        return abs(r1 - r2) <= 1 and abs(c1 - c2) <= 1 and (r1 != r2 or c1 != c2)

    # Build positions dictionary
    from collections import defaultdict
    positions = defaultdict(list)
    for i, ch in enumerate(s):
        if i < 13:
            positions[ch].append((0, i))
        else:
            positions[ch].append((1, i - 13))

    # Check if the path is valid
    for i in range(len(s) - 1):
        pos_current = positions[s[i]][0]
        pos_next = positions[s[i+1]][0]
        if not are_adjacent(pos_current, pos_next):
            return "Impossible"

    return f"{''.join(row1)}\n{''.join(row2)}"

