def is_tolerable(s, p):
    # Check if the string is tolerable (no palindromes of length 2 or more)
    # For length 2: no consecutive duplicates
    # For length 3: no palindrome 'aba'
    if len(s) >= 2:
        for i in range(len(s) - 1):
            if s[i] == s[i + 1]:
                return False
    if len(s) >= 3:
        for i in range(len(s) - 2):
            if s[i] == s[i + 2]:
                return False
    return True

def next_tolerable(s, n, p):
    # Try to find the next tolerable string lexicographically
    # Start from the end and try to increment
    for i in range(n - 1, -1, -1):
        # Try all characters from current + 1 up to p-1
        for c in range(ord(s[i]) + 1, ord('a') + p):
            new_s = s[:i] + chr(c) + s[i + 1:]

            # Check if this new string is tolerable
            # Also check if it's lexicographically larger
            if is_tolerable(new_s, p) and new_s > s:
                return new_s
    return "NO"

# Read input
n, p = map(int, input().split())
original = input()

# Find next tolerable string
result = next_tolerable(original, n, p)

# Output result
print(result)
