import itertools

def calculate_f(p):
    """Calculate f(p) for permutation p"""
    return sum(abs(p[i] - p[i+1]) for i in range(len(p)-1))

# Test for n=3
for p in itertools.permutations(range(1, 4)):
    f = calculate_f(p)
    print(f"{list(p)}: f = {f}")

# Find all permutations of 1..n with maximum f(p)

if __name__ == "__main__":
    n, m = map(int, input().split())
    result = find_lexicographically_mth(n, m)
    print(" ".join(map(str, result)))
"}

{"code": "
import itertools

def calculate_f(p):
    """Calculate f(p) for permutation p"""
    return sum(abs(p[i] - p[i+1]) for i in range(len(p)-1))

def find_lexicographically_mth(n, m):
    """Find the m-th permutation with maximum f(p) lexicographically"""
    permutations = [tuple(p) for p in itertools.permutations(range(1, n+1))]
    f_values = {p: calculate_f(p) for p in permutations}

    # Find maximum f(p)
    max_f = max(f_values.values())

    # Filter permutations to keep only those with maximum f(p)
    max_permutations = [p for p, f in f_values.items() if f == max_f]

    # Sort lexicographically
    max_permutations.sort()

    # Return m-th one (1-indexed)
    return list(max_permutations[m-1])

if __name__ == "__main__":
    n, m = map(int, input().split())
    result = find_lexicographically_mth(n, m)
    print(" ".join(map(str, result)))
"}

