def fibonacci_sum(n):
    """Find the maximum number of games the winner can play in a tournament with n players."""

    # Generate Fibonacci sequence up to n
    fib = [0, 1]
    while fib[-1] < n:
        fib.append(fib[-1] + fib[-2])

    # Calculate prefix sums of Fibonacci numbers
    prefix_sums = [0]
    for i in range(1, len(fib)):
        prefix_sums.append(prefix_sums[-1] + fib[i])

    # Find maximum k such that prefix_sum[k] <= n-1
    result = 0
    for i in range(1, len(prefix_sums)):
        if prefix_sums[i] <= n - 1:
            result = i
        else:
            break

    return result

# Read input and output result
n = int(input())
print(fibonacci_sum(n))
