def is_warm(x, y, radiators):
    """Check if a general at (x, y) is warm (within any radiator's heating area)."""
    for xi, yi, ri in radiators:
        dx = x - xi
        dy = y - yi
        if dx*dx + dy*dy <= ri*ri:
            return True
    return False

# Read input
xa, ya, xb, yb = map(int, input().split())
min_x = min(xa, xb)
max_x = max(xa, xb)
min_y = min(ya, yb)
max_y = max(ya, yb)

n = int(input())
radiators = []
for _ in range(n):
    xi, yi, ri = map(int, input().split())
    radiators.append((xi, yi, ri))

# Generate all perimeter points
# Left side (x = min_x)
for y in range(min_y, max_y + 1):
    if is_warm(min_x, y, radiators):
        continue
    print(f"General at ({min_x}, {y}) needs a blanket")

# Right side (x = max_x)
for y in range(min_y, max_y + 1):
    if is_warm(max_x, y, radiators):
        continue
    print(f"General at ({max_x}, {y}) needs a blanket")

# Top side (y = max_y) - skip corners
for x in range(min_x + 1, max_x):
    if is_warm(x, max_y, radiators):
        continue
    print(f"General at ({x}, {max_y}) needs a blanket")

# Bottom side (y = min_y) - skip corners
for x in range(min_x + 1, max_x):
    if is_warm(x, min_y, radiators):
        continue
    print(f"General at ({x}, {min_y}) needs a blanket")
