def is_tolerable(s):
    # Check substrings of length 2
    for i in range(len(s) - 1):
        if s[i] == s[i+1]:
            return False
    # Check substrings of length 3
    for i in range(len(s) - 2):
        if s[i] == s[i+2]:
            return False
    return True

def next_tolerable_string(s, p):
    n = len(s)

    # Find the rightmost character that can be incremented
    pos = n - 1
    while pos >= 0 and s[pos] == chr(ord('a') + p - 1):
        pos -= 1

    if pos < 0:
        return None

    # Increment the character at pos
    s = s[:pos] + chr(ord(s[pos]) + 1) + s[pos+1:]

    # Set all characters to the right to the smallest possible value
    for i in range(pos + 1, n):
        # Try each character from 'a' to the maximum allowed character
        for ch in range(ord('a'), ord('a') + p):
            candidate_char = chr(ch)

            # Check length 2 palindrome with previous character
            if i > 0 and s[i-1] == candidate_char:
                continue

            # Check length 3 palindrome with previous two characters
            if i > 1 and s[i-2] == candidate_char:
                continue

            # If both conditions are satisfied, use this character
            s = s[:i] + candidate_char + s[i+1:]
            break

    return s

n, p = map(int, input().split())
s = input()

result = next_tolerable_string(s, p)
