import sys

def longest_alternating_subsequence(s):
    """Compute the longest alternating subsequence length for binary string s"""
    transitions = 0
    for i in range(1, len(s)):
        if s[i] != s[i - 1]:
            transitions += 1
    return transitions + 1

def solve(s):
    n = len(s)

    # Original transitions
    original_transitions = 0
    for i in range(1, n):
        if s[i] != s[i - 1]:
            original_transitions += 1

    # Try all possible substrings to flip
    max_transitions = original_transitions

    # Try flipping substrings that start at each position
    for l in range(n):
        # Current value at left boundary
        left_val = s[l]
        # Value before left boundary (or 0 if l == 0)
        left_neighbor = s[l - 1] if l > 0 else None

        # Transition between left boundary and outside
        if left_neighbor is not None:
            if s[l] != s[l - 1]:
                original_transitions -= 1

        # Now expand to the right
        for r in range(l, n):
            # Transition between r and r+1
            if r < n - 1:
                if s[r] != s[r + 1]:
                    original_transitions -= 1

            # Flip at position r
            # Transition between r-1 and r
            if r > l:
                if s[r - 1] != s[r]:
                    original_transitions -= 1

            # Transition between r and r+1
            if r < n - 1:
                if s[r] != s[r + 1]:
                    original_transitions -= 1

            # Add the flipped value
            flip_val = '1' if s[r] == '0' else '0'

            # Transition between r-1 and flipped
            if r > l:
                if s[r - 1] != flip_val:
                    original_transitions += 1

            # Transition between flipped and r+1
            if r < n - 1:
                if flip_val != s[r + 1]:
                    original_transitions += 1

            # Update max
            max_transitions = max(max_transitions, original_transitions)

            # Restore for next iteration (but we could be smarter)
            # Instead of restoring, we could just recalculate at each step
            # Let's recalculate at each step instead

    return max_transitions + 1

if __name__ == "__main__":
    data = sys.stdin.read().split()
    if data:
        n = int(data[0])
        s = data[1] if len(data) > 1 else ""
        result = solve(s)
        print(result)
