    i = idx['['][0]

    # Find first ':' after i
    found_colon = False
    for j in idx[':']:
        if j > i:
            found_colon = True
            break
    if not found_colon:
        return -1

    # Find last ':' before last ']
    # Find last ']
    last_brace = idx[']'][-1]

