    # Find first '['
    first_open = idx['['][0]
    # Find last ']
    last_close = idx[']'][-1]

    # Check if ']' comes after '['
    if last_close < first_open:
        print(f"Last ']: {last_close}, First '[": {first_open}, Condition: last_close < first_open -> True, return -1")
        return -1

    # Find first ':' after first_open
    first_colon_after_open = None
    for i, ch in enumerate(s):
        if ch == ':' and i > first_open:
            first_colon_after_open = i
            break

    if first_colon_after_open is None:
        print("No ':' after '[', return -1")
        return -1

    # Find last ':' before last_close
    last_colon_before_close = None
    for i in range(len(s)-1, -1, -1):
        if s[i] == ':' and i < last_close and i > first_open:
            last_colon_before_close = i
            break

    if last_colon_before_close is None:
        print("No ':' before '], return -1")
        return -1

    # Count '|' between them
    pipe_count = 0
    for i, ch in enumerate(s):
        if first_colon_after_open < i < last_colon_before_close:
            if ch == '|':
                pipe_count += 1

    if pipe_count == 0:
        print(f"No pipes needed, return 4 (just [::])")
        return 4

    print(f"Pipes needed: {pipe_count}, return 4 + {pipe_count} = {4 + pipe_count}")
