def solve():
    n, m = map(int, input().split())
    initially_on = list(map(int, input().split()))
    initially_on.sort()

    # dp[i][j] = number of ways to turn on the first i lights with exactly j of them being initially on
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            # Case 1: don't turn on light i
            dp[i][j] = dp[i-1][j]

            # Case 2: turn on light i
            if j > 0 and i > 1 and dp[i-1][j-1] > 0:
                dp[i][j] = (dp[i][j] + dp[i-1][j-1]) % MOD

