def is_finite(p, q, b):
    if p == 0:
        return True

    # Reduce fraction
    from math import gcd
    g = gcd(p, q)
    num = p // g
    den = q // g

    # Check if denominator has only prime factors present in b
    def prime_factors(n):
        factors = set()
        # Divide out 2
        if n % 2 == 0:
            factors.add(2)
            while n % 2 == 0:
                n //= 2

        # Check odd factors up to sqrt(n)
        i = 3
        while i * i <= n:
            if n % i == 0:
                factors.add(i)
                while n % i == 0:
                    n //= i
            i += 2

        if n > 1:
            factors.add(n)
        return factors

    den_factors = prime_factors(den)
    b_factors = prime_factors(b)

    return den_factors.issubset(b_factors)

