def find_kth_greater(s, k, char_set):
    """
    Find the lexicographically smallest string of length k using only characters in char_set
    that is greater than the prefix of s of length k
    """
    n = len(s)
    prefix = s[:k]

    # Try to increase at each position and find the minimum result
    min_result = None

    for i in range(k):
        current_char = prefix[i]

        # Try all characters in char_set that are greater than current_char
        min_char = None
        for ch in sorted(char_set):
            if ch > current_char:
