import sys

def find_kth_greater(s, k, char_set):
    """
    Find the lexicographically smallest string of length k using only characters in char_set
    that is greater than the prefix of s of length k
    """
    n = len(s)
    prefix = s[:k]

    # Try to increase at each position and find the minimum result
    min_result = None

    for i in range(k):
        current_char = prefix[i]

        # Try all characters in char_set that are greater than current_char
        min_char = None
        for ch in sorted(char_set):
            if ch > current_char:
                if min_char is None or ch < min_char:
                    min_char = ch

        if min_char is not None:
            # Construct the result: keep the prefix up to i, change i to min_char, fill rest with smallest
            result = prefix[:i] + min_char
            for _ in range(k - i - 1):
                result += sorted(char_set)[0]

            if min_result is None or result < min_result:
                min_result = result

    if min_result is not None:
        return min_result

    # If we can't increase at any position, we need to increase at position k (i.e., add more characters)
    return prefix + ''.join(sorted(char_set)) * (k - n)

n, k = map(int, sys.stdin.readline().split())
s = sys.stdin.readline().strip()

char_set = set(s)
char_list = sorted(char_set)

if k <= n:
    t = find_kth_greater(s, k, char_set)
else:
    # We can just take s and add the smallest possible characters
    result = s + ''.join(sorted(char_set)) * (k - n)
    t = result

print(t)

