def solve(s):
    # Count letter frequencies
    freq = {}
    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1

    # Find the duplicate character
    duplicate = None
    for ch, count in freq.items():
        if count == 2:
            duplicate = ch
            break

    # If no duplicate found, impossible (shouldn't happen)
    if duplicate is None:
        return "Impossible"

    # Create a 2x13 grid (list of lists)
    grid = [['' for _ in range(13)] for _ in range(2)]

    # Place characters in the grid
    place_idx = 0
    for i in range(2):
        for j in range(13):
            if place_idx >= 26:
                break

            # We need to handle the duplicate
            if s[place_idx] == duplicate and place_idx == 13:
                # Place duplicate at (1,12) for the second row
                grid[1][12] = duplicate
                place_idx += 1
                continue

            # Try to place the character at this grid position
            if grid[i][j] == '':
                grid[i][j] = s[place_idx]
                place_idx += 1

    # Check if we placed all characters
    if place_idx != 26:
        return "Impossible"

    # Now check if a path exists that spells the string
    # We need to check if consecutive characters are adjacent
    # Let's just try to trace the path

    # Find starting position of the first character
    start_row, start_col = -1, -1
    for i in range(2):
        for j in range(13):
            if grid[i][j] == s[0]:
                start_row, start_col = i, j
                break
        if start_row != -1:
            break

    # Trace the path
    path = []
    row, col = start_row, start_col
    path.append((row, col))

    for i in range(1, 27):
        next_char = s[i]
        next_row, next_col = -1, -1

        # Check all 8 possible neighbors
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue

                new_r = row + dr
                new_c = col + dc

                if 0 <= new_r < 2 and 0 <= new_c < 13:
                    if grid[new_r][new_c] == next_char:
                        next_row, next_col = new_r, new_c
                        break
            if next_row != -1:
                break

        if next_row == -1:
            return "Impossible"

        row, col = next_row, next_col
        path.append((row, col))

    return "".join(grid[0]) + "\n" + "".join(grid[1])

s = input().strip()
