import sys

def solve():
    n = int(sys.stdin.readline())
    permutation = list(map(int, sys.stdin.readline().split()))

    # Find the first and last position where permutation differs from original
    start = 0
    while start < n and permutation[start] == start + 1:
        start += 1

    end = n - 1
    while end >= 0 and permutation[end] == end + 1:
        end -= 1

    # If no differences, output 0 0
    if start >= n or end < 0:
        print("0 0")
        return

    # Check if reversing [start, end] gives the correct permutation
    original = list(range(1, n + 1))
    reversed_segment = original[:start] + original[start:end+1][::-1] + original[end+1:]

    if reversed_segment == permutation:
        print(f"{start + 1} {end + 1}")
    else:
        print("0 0")

if __name__ == "__main__":
    solve()
"}

