from collections import defaultdict

def solve():
    n = int(input())
    freq = defaultdict(int)

    for _ in range(n):
        s = input().strip()
        count = [0] * 26
        for c in s:
            count[ord(c) - ord('a')] += 1

        mask = 0
        length = 0
        for i in range(26):
            if count[i] % 2 == 1:
                mask |= (1 << i)
            length += count[i]

        freq[(mask, length)] += 1

    result = 0
    for (m1, l1), cnt1 in freq.items():
        for (m2, l2), cnt2 in freq.items():
            if m1 == m2 and l1 == l2:
                # Count pairs within the same group
                result += cnt1 * (cnt1 - 1) // 2
                continue

            combined_mask = m1 ^ m2

            if (l1 + l2) % 2 == 0:
                # Total length even, need all even counts
                if combined_mask == 0:
                    result += cnt1 * cnt2
            else:
                # Total length odd, need exactly one character with odd count
                if (combined_mask & (combined_mask - 1)) == 0:
                    result += cnt1 * cnt2

    print(result)

solve()
"}

