import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Find the smallest k > 1 that divides some prefix sums
    total = sum(a)
    if total == 0:
        print(0)
        return

    # Find all divisors of total
    divisors = set()
    for i in range(1, int(total**0.5) + 1):
        if total % i == 0:
            divisors.add(i)
            divisors.add(total // i)

    min_moves = float('inf')

    # Try each divisor (excluding 1)
    for k in divisors:
        if k == 1:
            continue

        # Find positions where cumulative sum is divisible by k
        prefix = 0
        positions = []
        for i in range(n):
            prefix += a[i]
            if prefix % k == 0:
                positions.append(i)

        if len(positions) < 1:
            continue

        # Try taking the last possible position
        # We want to minimize moves, so take the largest valid position
        last_pos = positions[-1]
        total_moves = 0

        # Move all chocolates to last_pos
        for i in range(n):
            if i != last_pos:
                moves = abs(last_pos - i)
                total_moves += a[i] * moves

        if total_moves < min_moves:
            min_moves = total_moves

    if min_moves == float('inf'):
        print(-1)
    else:
        print(min_moves)

if __name__ == '__main__':
    solve()
