def dfs(graph, start, visited):
    stack = [start]
    visited.add(start)
    component = [start]

    while stack:
        node = stack.pop()
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                component.append(neighbor)
                stack.append(neighbor)

    return component

