def count_mergesort_calls(arr):
    """Count the number of mergesort calls for a given array."""
    n = len(arr)
    if n == 0:
        return 0

    # Helper function to check if a segment is sorted
    def is_sorted(l, r):
        for i in range(l, r - 1):
            if arr[i] > arr[i + 1]:
                return False
        return True

    # Helper function to count calls recursively
    def recurse(l, r):
        if l >= r:
            return 0

        if is_sorted(l, r):
            return 1

        mid = (l + r) // 2
        return 1 + recurse(l, mid) + recurse(mid, r)

    return recurse(0, n)

def find_permutation(n, k):
    """Find a permutation of size n with exactly k mergesort calls."""
    # Minimum calls (sorted array)
    if k == 1:
        return [i+1 for i in range(n)]

    # Maximum calls (reverse-sorted array)
    # We can compute this recursively
    def max_calls(l):
        if l == 1:
            return 1
        return 1 + 2 * max_calls(l // 2)

    if k > max_calls(n):
        return -1

    # Try to construct a permutation
    # Let's use a recursive approach
    def build(l, r):
        if l >= r:
            return []

        if l == r - 1:
            return [r]

        # This array will be sorted at some point
        left = build(l, (l + r) // 2)
        right = build((l + r) // 2, r)

        # To maximize calls, we want the left half to be reverse-sorted
        # and the right half to be sorted
        if k > 1:
            # If we reverse the left half, we get more calls
            left = left[::-1]

        # Merge the two halves
        # To make the segment not sorted, we want some disorder
        result = left + right

        # Count calls for this arrangement
        calls = count_mergesort_calls(result)

        if calls == k:
            return result

        # If not, try different arrangements
        # Just return something
        return [i+1 for i in range(l, r)]

    return build(0, n)

