import sys
from collections import deque

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    top_row = next(it)
    bot_row = next(it)

    # Create grid as a dictionary of booleans (True = obstacle, False = empty)
    grid = {}
    for i in range(1, n + 1):
        grid[i] = (top_row[i-1] == 'X')
        grid[n + i] = (bot_row[i-1] == 'X')

    # BFS function
    def bfs(start, target) -> int:
        if start == target:
            return 0

        visited = [False] * (2 * n + 1)
        queue = deque([(start, 0)])
        visited[start] = True

        while queue:
            cell, dist = queue.popleft()

            # Skip obstacles
            if grid[cell]:
                continue

            # Find neighbors
            if 1 <= cell <= n:
                # Top row cell
                for neighbor in [cell - 1, cell + 1, n + cell]:
                    if 1 <= neighbor <= 2 * n and not grid[neighbor] and not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append((neighbor, dist + 1))

                        if neighbor == target:
                            return dist + 1
            else:
                # Bottom row cell (n < cell <= 2n)
                # Extract position in bottom row: cell - n
                for neighbor in [cell - 1, cell + 1, cell - n]:
                    if 1 <= neighbor <= 2 * n and not grid[neighbor] and not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append((neighbor, dist + 1))

                        if neighbor == target:
                            return dist + 1

        return -1

    # Process queries
    result = []
    for _ in range(m):
        v = int(next(it))
        u = int(next(it))
        result.append(str(bfs(v, u)))

    sys.stdout.write("\n".join(result))

if __name__ == "__main__":
    solve()
"}

