def solve():
    n, d, h = map(int, sys.stdin.readline().split())

    if n < d + 1:
        print(-1)
        return

    if d > h and d > 2 * h:
        print(-1)
        return

    edges = []

    # Root is vertex 1
    root = 1

    if d > h:
        # branch1: length h
        for i in range(1, h + 1):
            edges.append((root, i + 1))

        # branch2: length d - h
        for i in range(h + 2, h + 2 + (d - h)):
            edges.append((root, i))

        # Remaining vertices attached to root
        for i in range(h + 2 + (d - h), n + 1):
            edges.append((root, i))
    else:  # d == h
        # single branch of length h
        for i in range(1, h + 1):
            edges.append((root, i + 1))

        # Remaining vertices attached to root
        for i in range(h + 1, n + 1):
            edges.append((root, i))

    for u, v in edges:
        print(u, v)

solve()
