from collections import deque
import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    max_val = 100000  # Since ai <= 10^5
    count = [0] * (max_val + 1)
    for x in a:
        count[x] += 1
    # Build missing set: numbers from 1..n that are not in a
    missing = deque()
    for x in range(1, n + 1):
        if count[x] == 0:
            missing.append(x)
    result = []
    for x in a:
        if count[x] > 1:
            result.append(missing.popleft())
            count[x] -= 1
        else:
            result.append(x)
    print(' '.join(map(str, result)))

if __name__ == '__main__':
    solve()
"}

