    data = sys.stdin.read().strip().split()
    if not data:
        return
    m = int(data[0])
    n = int(data[1])
    a = list(map(int, data[2:2+n]))

    if n == 1:
        print(a[0], 0)
        return

    a.sort()

    # Try all possible differences
    for i in range(n):
        for j in range(i+1, n):
            d = (a[j] - a[i]) % m
            valid = True

            # Check if all elements match x + kd mod m where x = a[i] and k = 0..n-1
            for k in range(n):
                target = (a[i] + k * d) % m
                if target != a[k]:
                    valid = False
                    break

            if valid:
                print(a[i], d)
                return

    print(-1)

if __name__ == "__main__":
    solve()
