import sys

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def are_coprime(num, factors):
    # Check if num shares any prime factor with factors
    for prime in factors:
        if num % prime == 0:
            return False
    return True

def smallest_coprime(start, forbidden_primes):
    # Find smallest number >= start that is coprime with all forbidden_primes
    for num in range(start, 10**6):
        if are_coprime(num, forbidden_primes):
            return num
    return -1  # Not found (shouldn't happen in problem constraints)

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    b = []
    used_primes = set()

    for num in a:
        # Check if num is coprime with all previous elements
        is_valid = True
        for prime in used_primes:
            if num % prime == 0:
                is_valid = False
                break

        if is_valid:
            b.append(num)
            # Update used_primes with prime factors of num
            temp = num
            for prime in range(2, int(temp**0.5) + 1):
                if temp % prime == 0:
                    used_primes.add(prime)
            if temp > 1:
                used_primes.add(temp)
        else:
            # Find smallest coprime number >= num
            res = smallest_coprime(num, used_primes)
            b.append(res)
            # Update used_primes with prime factors of res
            temp = res
            for prime in range(2, int(temp**0.5) + 1):
                if temp % prime == 0:
                    used_primes.add(prime)
            if temp > 1:
                used_primes.add(temp)

    print(' '.join(map(str, b)))

if __name__ == "__main__":
    solve()
"}

