def solve(n: int, k: int) -> int:
    MOD = 998244353

    # Calculate factorials
    fact_n = 1
    for i in range(1, n + 1):
        fact_n = (fact_n * i) % MOD

    row_ways = (n * fact_n) % MOD
    col_ways = (n * fact_n) % MOD
    perm_ways = fact_n % MOD

    if k > n * (n - 1) // 2:
        return 0

    if k == n * (n - 1) // 2:
        return (row_ways + col_ways) % MOD

    if k == 0:
        return perm_ways

    return 0


