            return False
        if i > 1 and s[i] == s[i-2]:
            return False
    return True

def find_next_tolerable(s, p):
    """Find the lexicographically next tolerable string"""
    s = s[:]

    # Try to increment from right to left
    for i in range(n-1, -1, -1):
        # Find next valid character for position i
        if ord(s[i]) < ord('a') + p - 1:
            next_char = chr(ord(s[i]) + 1)

            # Check if we can place next_char at position i
            new_s = s[:i] + [next_char] + s[i+1:]

            # If we can place it, try to fill the rest of the positions
            # from right to left to make the string as small as possible
            # that is larger than the given string
            if is_tolerable(new_s):
                # We need to fill the remaining positions from right to left
                # with the smallest valid characters
                filled_s = new_s[:]

                # Fill positions from right to left
                for j in range(i+1, n):
                    if ord(filled_s[j]) < ord('a') + p - 1:
                        filled_s[j] = chr(ord('a') + p - 1)

                # Check if filled_s is tolerable
                if is_tolerable(filled_s):
