for i in range(len(expression)):
    for j in range(i, len(expression)):
        # Calculate expression with brackets from i to j (inclusive)
        # This is a bit tricky: we need to construct a new expression
        # with brackets around positions i to j

        # The subexpression from i to j
        sub_expr = ''.join(expression[i:j+1])

        # The expression before i (if any)
        if i > 0:
            before = ''.join(expression[0:i])
            if before[-1] in '+*':
                before = before + ' ' + sub_expr
            else:
                before = before + sub_expr
        else:
            before = sub_expr

        # The expression after j+1 (if any)
        after = ''.join(expression[j+1:])

        # If after starts with + or *, we need to add a space
        if after and after[0] in '+*':
            after = ' ' + after

        # Combine before and after
        full_expr = before + after

        # Evaluate and update maximum
        value = evaluate(full_expr)
        if value > max_value:
            max_value = value

