def evaluate(expr):
    """Evaluate an expression with + and *"""
    try:
        return eval(expr)
    except:
        return float('inf')

# Read input
expr = input().strip()

# Extract digits and operators
expression = []
for i, ch in enumerate(expr):
    if i % 2 == 0:  # digit position
        expression.append(ch)
    else:  # operator position
        expression.append(ch)

max_value = float('-inf')

# Try all pairs (i, j) where i <= j
for i in range(len(expression)):
    for j in range(i, len(expression)):
        # Create a new expression with brackets around positions i to j (inclusive)
        new_expr = ''

        # Add the part before i
        new_expr += ''.join(expression[:i])

        # Add brackets around positions i to j
        if i > 0:
            new_expr += ' '  # Add space if there's something before
        new_expr += '(' + ''.join(expression[i:j+1]) + ')

        # Add the part after j+1
        if j+1 < len(expression):
            new_expr += ' '  # Add space if there's something after
            new_expr += ''.join(expression[j+1:])

