def solve():
    T = int(input())
    for _ in range(T):
        n, k = map(int, input().split())

        # Let's compute winning positions up to n to find the pattern
        winning = [False] * (n + 1)
        winning[0] = False  # position 0 is losing

        for i in range(1, n + 1):
            # Can move to i-1, i-2, or i-k
            if (i - 1 >= 0 and not winning[i-1]) or \
               (i - 2 >= 0 and not winning[i-2]) or \
               (i - k >= 0 and not winning[i-k]):
                winning[i] = True  # current position is winning
            else:
                winning[i] = False  # current position is losing

        # If the starting position is winning, Alice wins
        if winning[n]:
            print("Alice")
        else:
            print("Bob")

solve()
