def longest_fibonacci-ish(n, nums):
    from collections import Counter

    freq = Counter(nums)
    max_length = 0

    # Try all possible pairs for f0 and f1
    for f0, count0 in freq.items():
        for f1, count1 in freq.items():
            if f0 == f1:
                # If f0 and f1 are the same, we need at least two of them
                if count0 >= 2:
                    new_freq = freq.copy()
                    new_freq[f0] -= 2
                    if new_freq[f0] == 0:
                        del new_freq[f0]
                    length = 2

                    # Build Fibonacci-ish sequence
                    current_f0 = f0
                    current_f1 = f1
                    while True:
                        next_val = current_f1 + current_f0
                        if next_val in new_freq and new_freq[next_val] > 0:
                            new_freq[next_val] -= 1
                            if new_freq[next_val] == 0:
                                del new_freq[next_val]
                            length += 1
                            current_f0, current_f1 = current_f1, next_val
                        else:
                            break
                    max_length = max(max_length, length)
            else:
                # f0 and f1 are different
                if count0 > 0 and count1 > 0:
                    new_freq = freq.copy()
                    new_freq[f0] -= 1
                    if new_freq[f0] == 0:
                        del new_freq[f0]
                    new_freq[f1] -= 1
                    if new_freq[f1] == 0:
                        del new_freq[f1]
                    length = 2

                    # Build Fibonacci-ish sequence
                    current_f0 = f0
                    current_f1 = f1
                    while True:
