def can_be_fixed(a_sub):
    # Check if we can fix by changing one element
    bad_positions = []

    # Check if we can fix by changing an element at the start or end of the subsegment
    # That is, if there's a single bad position at the boundary

    # First, check if we can fix by changing the start
    if len(a_sub) >= 2 and a_sub[0] >= a_sub[1]:
        # Change a_sub[0] to something smaller than a_sub[1]
        # If a_sub[1] is the only bad position, it works
        # Actually, we need to check if the rest is good
        new_sub = [a_sub[1] - 1] + a_sub[1:]
        # Check if new_sub is strictly increasing
        is_good = True
        for i in range(len(new_sub) - 1):
            if new_sub[i] >= new_sub[i + 1]:
                is_good = False
                break
        if is_good:
            return True

    # Check if we can fix by changing the end
    if len(a_sub) >= 2 and a_sub[-2] >= a_sub[-1]:
        # Change a_sub[-1] to something larger than a_sub[-2]
        new_sub = a_sub[:-1] + [a_sub[-2] + 1]
        is_good = True
        for i in range(len(new_sub) - 1):
            if new_sub[i] >= new_sub[i + 1]:
                is_good = False
                break
        if is_good:
