import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        n = int(next(it))
        x = int(next(it))
        a = [int(next(it)) for _ in range(n)]
        odds = sum(1 for num in a if num % 2 == 1)
        evens = n - odds

        lower = max(0, x - evens)
        upper = min(odds, x)

        if lower > upper:
            out_lines.append("NO")
        else:
            # Check if interval contains any odd.
            if upper < lower:
                out_lines.append("NO")
                continue
            first_odd = lower
            if first_odd % 2 == 0:
                first_odd += 1
            if first_odd > upper:
                out_lines.append("NO")
            else:
                out_lines.append("YES")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
