n, m = map(int, input().split())
row1 = input().strip()
row2 = input().strip()

def get_position(pos):
    """Convert 1-based position to (row, col)"""
    if pos <= n:
        return (1, pos)
    else:
        return (2, pos - n)

def get_distance(pos1, pos2):
    """Calculate shortest distance between two positions"""
    row1, col1 = get_position(pos1)
    row2, col2 = get_position(pos2)

    # If same cell
    if row1 == row2 and col1 == col2:
        return 0

    # Same row
    if row1 == row2:
        return abs(col1 - col2)

    # Different rows
    if col1 == col2:
        # Direct vertical movement
        return 1
    else:
        # Need to move horizontally and then vertically
        return abs(col1 - col2) + 1

for _ in range(m):
    v, u = map(int, input().split())
    print(get_distance(v, u))
