import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    a = []
    for _ in range(n):
        a.append(int(next(it)))
    b = []
    for _ in range(n):
        b.append(int(next(it)))

    def compute_needed(x):
        needed = 0
        for ai, bi in zip(a, b):
            need = ai * x - bi
            if need > 0:
                needed += need
                if needed > k:
                    break
        return needed

    low = 0
    high = max((b[i] + k) // a[i] for i in range(n))
    best = 0

    while low <= high:
        mid = (low + high) // 2
        needed = compute_needed(mid)
        if needed <= k:
            best = mid
            low = mid + 1
        else:
            high = mid - 1

    print(best)

if __name__ == "__main__":
    solve()
"}

