import sys
from collections import Counter

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    strings = data[1:n+1]

    # Precompute parity masks
    masks = []
    for s in strings:
        mask = 0
        for c in s:
            bit = ord(c) - ord('a')
            mask ^= (1 << bit)
        masks.append(mask)

    # Count frequencies of each mask
    freq = Counter(masks)

    ans = 0
    # Process each unique mask
    for mask1, count1 in freq.items():
        for mask2, count2 in freq.items():
            if mask1 > mask2:
                continue

            xor_mask = mask1 ^ mask2
            # Check if we can form a palindrome with concatenated string
            # If XOR has at most one bit set, then it's valid
            if bin(xor_mask).count('1') <= 1:
                if mask1 == mask2:
                    # Pairs within the same mask: count1 * (count1 - 1) / 2
                    ans += count1 * (count1 - 1) // 2
                else:
                    # Pairs between different masks
                    ans += count1 * count2

    print(ans)

if __name__ == "__main__":
    solve()
